import base64
import streamlit as st
import streamlit.components.v1 as components

st.set_page_config(
    page_title="Aatoksen ja Villen Forssa-Peli", page_icon="🚜", layout="wide"
)

st.title("🚜 Aatoksen ja Villen Forssa-Peli: Raviradan Kunnossapito 🚛")
st.caption(
    "Ohjaa vesiautoa nuolinäppäimillä tai WASD:lla. Kastele rata ja väistä traktoreita!"
)

# Täysin korjattu HTML/JS-peli Base64-muodossa
b64_game = ""

# Korjataan b64-merkkijonon virheellinen funktio kutsumalla drawTractor (ilman viivaa)
game_html = base64.b64decode(b64_game.encode("utf-8")).decode("utf-8")
game_html = game_html.replace("draw-Tractor", "drawTractor")

components.html(game_html, height=640)
